  if(vault&&!vaultKey){showVaultDialog("unlock");return}
  marketRefreshPending = false;
  const debtDraft = new Map(['debtPayoff','debtPayment','debtMonths','debtCET'].map(id => [id, $('#'+id)?.value]));
